def determine_parts(en, cat, sub):
    en_lower = en.lower()
    # Check if photo description
    if any(k in en_lower for k in [
        'is taking a picture', 'picture was taken', 'is taking an order',
        'is entering an old-looking', 'is doing an experiment',
        'is going up the stairs', 'is going along the river',
        'is taking notes', 'are having a meeting', 'are taking a break'
    ]):
        return [2]
    
    if cat == 'core_verb':
        return [3, 5]
    elif cat == 'topic':
        return [3, 5]
    elif cat == 'pattern':
        return [3, 5]
    elif cat == 'modifier':
        return [3, 5]
    return [3, 5]

print(f"Total PDF entries defined: {len(pdf_entries)}")

with open('parse_pdfs.py', encoding='utf-8') as f:
    c = f.read()
lines = [l.strip() for l in c.split('text = """')[1].split('"""')[0].split('\n') if l.strip()]

def norm(s):
    return re.sub(r'[^a-zA-Z0-9]', '', s).lower()

mismatches = []
for i in range(min(len(lines), len(pdf_entries))):
    if norm(lines[i]) != norm(pdf_entries[i]['en']):
        mismatches.append((i, lines[i], pdf_entries[i]['en']))

print('Mismatches count:', len(mismatches))
for m in mismatches[:10]:
    print(m)

